sys_ui_action.client_script_v2:
function onClick(g_form) {
    //MSSOTIQUBE-1852
    g_modal.confirm('Do you want to perform Trade Maintenance for this trade. Proceed?', function(confirmed) {
        if (confirmed == true) {
            var trdCase = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
            trdCase.addParam('sysparm_name', 'createManualTradeBulkID'); // Create a Bulk ID and Trade Case
            trdCase.addParam('sysparm_trdID', g_form.getUniqueValue());
            trdCase.getXMLAnswer(handleAnswer);

        }
    });

    function handleAnswer(response) {
        if (response) {
            var url = ("x/hsb11/mss-custody-workspace/record/x_hsb11_mss_c_proc_mss_custody_trade/" + g_form.getUniqueValue() + "/sub/record/x_hsb11_hsbc_mss_o_hsbc_bulk_transaction/" + response); // Navigate to Bulk ID
            top.window.location = url; // Refresh trade to disable the UI action
            //MSSOTIQUBE-1852
        }
    }
}

sys_ui_action.script:
function trigManualCase() {

    var gm = new GlideModal("glide_confirm_basic", true, 600);
    gm.setTitle("Manual Maintenance");
    gm.setPreference("title", "Do you want to perform Trade Maintenance for this trade. Proceed?");
    gm.setPreference("onPromptComplete", function() {
        //Triggering Manual Case Creation
        var trdCase = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
        trdCase.addParam('sysparm_name', 'createManualTradeBulkID'); // Create a Bulk ID and Trade Case
        trdCase.addParam('sysparm_trdID', g_form.getUniqueValue());
        trdCase.getXMLAnswer(handleAnswer);

        function handleAnswer(response) {
            if (response) {
                var url = ("/x_hsb11_hsbc_mss_o_hsbc_bulk_transaction.do?sys_id=" + response); // Navigate to Bulk ID
                //g_navigation.open(url, '_blank');
                top.window.location = url; // Refresh trade to disable the UI action
            }
        }

        //Triggering Manual Case Creation
    });
    gm.setPreference("onPromptCancel", function() {
        location.reload();
    });
    gm.render();



}
